using System;using System.IO;using System.Linq;using ArcCap;
class Xe1PatchTests {
 static int passed;static void Check(bool good,string name){if(!good)throw new Exception(name);passed++;Console.WriteLine("PASS "+name);}static void Reject(Action action,string name){try{action();}catch(InvalidDataException){Check(true,name);return;}throw new Exception("Expected rejection: "+name);}
 static int Main(string[]args){for(int index=0;index<2;index++){
  byte[] original=File.ReadAllBytes(args[index]);var d=Xe1Patch.Definitions[index];Check(Engine.Hash(original)==d.Original,"Pinned original "+d.Version);Check(DriverCatalog.CandidateOffsets(original).SequenceEqual(new[]{d.Offset}),"Reviewed constructor mapping "+d.Version);
  byte[] patched=DriverTrial.Patch(original,1024);Check(Engine.Hash(patched)==d.OneGiB,"Pinned 1 GiB output "+d.Version);Check(BitConverter.ToInt32(patched,d.Offset+16)==0x40000000,"1 GiB immediate stored "+d.Version);
  Array.Copy(original,d.Offset+16,patched,d.Offset+16,4);Check(patched.SequenceEqual(original),"All other bytes preserved "+d.Version);Check(Xe1Patch.Patch(original,512).SequenceEqual(original),"Unchanged control "+d.Version);
  var changed=(byte[])original.Clone();changed[d.Offset+22]^=1;Reject(()=>Xe1Patch.Patch(changed,1024),"Changed context refused "+d.Version);changed=(byte[])original.Clone();changed[0x2000]^=1;Reject(()=>Xe1Patch.Patch(changed,1024),"Unrelated modifications refused "+d.Version);Check(DriverCatalog.CandidateOffsets(changed).Length==0,"Unknown Xe1 image cannot inherit support "+d.Version);
  Reject(()=>Xe1Patch.Patch(original,2048),"Unverified 2 GiB refused "+d.Version);Reject(()=>Xe1Patch.Patch(original,4096),"Unverified 4 GiB refused "+d.Version);
  string output=Path.Combine(args[2],"xe1-"+d.Version+"-constructor.bin");byte[] code=Xe1Patch.Patch(original,1024).Skip(d.Offset).Take(113).ToArray();File.WriteAllBytes(output,code);
 }Check(DriverTrial.SupportedName("igd12um64xeh.dll"),"Xe1 accepted by isolated test workflow");Check(!DriverTrial.SupportedName("igd12um64xel.dll"),"Older Xe-L is not silently treated as Xe1");Check(DriverCatalog.PrefersXe1("Intel(R) Arc(TM) A770 Graphics")&&DriverCatalog.PrefersXe1("Intel Arc Pro A50 Graphics"),"A-series names suggest the Xe1 test");Check(!DriverCatalog.PrefersXe1("Intel Arc B580 Graphics"),"B-series is not treated as Xe1");Check(DriverTrial.CompatibleProofHelper("348B383C32D4FBC8EFC5A6DD0D053CF8C9521CC2E8A763EFC25D378B47EE88EA","NEW","igd12um64xe2.dll"),"Previous genuine Xe2 results remain usable");Check(!DriverTrial.CompatibleProofHelper("348B383C32D4FBC8EFC5A6DD0D053CF8C9521CC2E8A763EFC25D378B47EE88EA","NEW","igd12um64xeh.dll"),"An old helper cannot supply Xe1 proof");Check(!DriverTrial.CompatibleProofHelper("UNKNOWN","NEW","igd12um64xe2.dll"),"Unknown historical helper hashes refused");Console.WriteLine("Passed "+passed+" Xe1 checks; only temporary constructor snippets were written.");return 0;}
}
